{
  "unit": 40,
  "font": "sans",
  "caption": "Fig. 1.1",
  "points": {
    "O": {"at": [0, 0], "dot": true, "label": "0", "labelDir": "sw"},
    "tX": {"at": [3, 0], "dot": true, "label": "t_{X}", "labelDir": "s"},
    "tY": {"at": [6, 0], "dot": true, "label": "t_{Y}", "labelDir": "s"},
    "tZ": {"at": [9, 0], "dot": true, "label": "t_{Z}", "labelDir": "s"},
    "vX": {"at": [0, -4], "dot": true, "label": "-v_{1}", "labelDir": "w"},
    "vY": {"at": [0, 5], "dot": true, "label": "v_{2}", "labelDir": "w"},
    "X": {"at": [3, -4]},
    "Y": {"at": [6, 5]},
    "Z": {"at": [9, 0]}
  },
  "elements": [
    {
      "type": "axes",
      "x": {"min": 0, "max": 10, "step": 2, "label": "t / s", "numbers": false},
      "y": {"min": -5, "max": 6, "step": 2, "label": "v / m s^{-1}", "numbers": false}
    },
    {
      "type": "segment",
      "from": [0, -2],
      "to": "X",
      "style": "solid",
      "weight": "normal"
    },
    {
      "type": "segment",
      "from": "X",
      "to": "Y",
      "style": "solid",
      "weight": "normal",
      "curve": 0.2
    },
    {
      "type": "segment",
      "from": "Y",
      "to": "Z",
      "style": "solid",
      "weight": "normal"
    },
    {
      "type": "segment",
      "from": [3, 0],
      "to": "X",
      "style": "dashed",
      "weight": "thin"
    },
    {
      "type": "segment",
      "from": [6, 0],
      "to": "Y",
      "style": "dashed",
      "weight": "thin"
    },
    {
      "type": "segment",
      "from": [0, 5],
      "to": "Y",
      "style": "dashed",
      "weight": "thin"
    },
    {
      "type": "segment",
      "from": [0, -4],
      "to": "X",
      "style": "dashed",
      "weight": "thin"
    }
  ]
}

